package com.petstore.api.report;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

import io.restassured.filter.Filter;
import io.restassured.filter.FilterContext;
import io.restassured.response.Response;
import io.restassured.specification.FilterableRequestSpecification;
import io.restassured.specification.FilterableResponseSpecification;

/**
 * A RestAssured filter that records each call for the HTML report.
 *
 * <p>Registered inside {@code ApiClient.spec()}, so it sits on the request path.
 * That is the whole point: test code hands the listener nothing and cannot forget
 * to, and there is no shared mutable accumulator for tests to corrupt. The deque
 * is a ThreadLocal, and TestNG runs a test method on one thread, so its lifetime
 * matches the test exactly.
 *
 * <p>Credentials are stripped before an {@link ApiCall} exists, via
 * {@link TestLog#redact}. Reports get shared and emailed and the log file is
 * written to disk; a bearer token in either is the most plausible way this suite
 * could leak one.
 */
public final class CallRecorder implements Filter {

    /** Keeps memory bounded when a test makes many calls. */
    private static final int MAX_CALLS = 20;

    private static final int MAX_BODY_BYTES = 4000;

    private static final ThreadLocal<Deque<ApiCall>> CALLS = ThreadLocal.withInitial(ArrayDeque::new);

    @Override
    public Response filter(
            FilterableRequestSpecification req,
            FilterableResponseSpecification res,
            FilterContext ctx) {

        long started = System.currentTimeMillis();
        Response response = ctx.next(req, res);
        long millis = System.currentTimeMillis() - started;

        Deque<ApiCall> q = CALLS.get();
        if (q.size() >= MAX_CALLS) q.removeFirst();

        String responseBody;
        try {
            // Redacted like the request. The response is where the credentials
            // actually are: a login answers with the JWT pair, and these bodies go
            // to the console, the log file and the HTML report — three places a
            // token outlives the run it came from.
            responseBody = truncate(TestLog.redact(response.asString()));
        } catch (Exception e) {
            // A non-text or already-consumed body must not break the test.
            responseBody = "<unreadable: " + e.getClass().getSimpleName() + ">";
        }

        // Bind to Object first. getBody() is declared <T> T, so passing it
        // straight into String.valueOf(...) makes javac infer T = char[] and pick
        // the String.valueOf(char[]) overload — which compiles and then throws
        // ClassCastException at runtime on every request that has a body.
        Object rawBody = req.getBody();
        String requestBody = truncate(TestLog.redact(rawBody == null ? null : rawBody.toString()));

        q.addLast(
                new ApiCall(
                        req.getMethod(),
                        req.getURI(),
                        response.statusCode(),
                        millis,
                        requestBody,
                        responseBody));

        // Logged as it happens, not at the end of the test. A run that hangs or is
        // killed still leaves the last call it made in the console and the log
        // file; the report only exists once the suite finishes.
        TestLog.info(
                req.getMethod()
                        + " "
                        + req.getURI()
                        + " -> "
                        + response.statusCode()
                        + " ("
                        + millis
                        + "ms)");
        TestLog.block("request body:", requestBody);
        // The response is logged on success too. On a pass it is how you confirm
        // the test asserted something real rather than a 200 with an empty body.
        TestLog.block("response body:", responseBody);

        return response;
    }

    /** Oldest first. */
    public static List<ApiCall> drain() {
        List<ApiCall> out = new ArrayList<>(CALLS.get());
        CALLS.get().clear();
        return out;
    }

    public static void clear() {
        CALLS.get().clear();
    }

    private static String truncate(String s) {
        if (s == null) return null;
        if (s.length() <= MAX_BODY_BYTES) return s;
        return s.substring(0, MAX_BODY_BYTES) + "\n…truncated " + (s.length() - MAX_BODY_BYTES) + " chars";
    }

}
